tests.pseudocode:
idx := &fakeIndex{}
opts := issuetriage.Options{Index: idx, ...}
// verify that the Config built from opts carries idx as Config.Index

idx := &fakeIndex{}
opts := codefix.Options{Index: idx, ...}
// verify that the Config built from opts carries idx as Config.Index

idx := &fakeIndex{}
opts := specgen.Options{Index: idx, ...}
// verify that the Config built from opts carries idx as Config.Index

idx := &fakeIndex{}
opts := codeimpl.Options{Index: idx, ...}
// verify that the Config built from opts carries idx as Config.Index

idx := &fakeIndex{}
cfg := fauxConfig(provider, ws)
cfg.Index = idx
phase.BuiltinTools = append(agentrun.ReadOnlyFileTools, "code_search")
resolved, _ := runner.registeredTools(phase)
assert containsTool(resolved, "code_search")
for _, name := range agentrun.ReadOnlyFileTools {
  assert containsTool(resolved, name)
}

resolved := []core.Tool{{Name: "code_search"}, {Name: "read_file"}, {Name: "list_files"}, {Name: "find_files"}, {Name: "search_files"}}
err := agentrun.AssertReadOnly(resolved)
assert err == nil

idx := &recordingIndex{}
// simulate successful run with deferred idx.Close()
runEntryPoint(ctx, idx)
assert idx.closeCalls == 1

idx := &recordingIndex{}
// simulate failing run with deferred idx.Close()
runEntryPointThatFails(ctx, idx)
assert idx.closeCalls == 1

idx := &recordingIndex{}
opts := codefix.Options{Index: idx, ...}
result, _ := codefix.Run(ctx, opts)
assert idx.invalidateCalls >= 1
assert idx.invalidateArgs[0] == ""
assert idx.invalidateTimestamp < implementPhaseStartTimestamp

idx := &recordingIndex{}
opts := codeimpl.Options{Index: idx, ...}
result, _ := codeimpl.Run(ctx, opts)
assert idx.invalidateCallsContain("")
assert idx.callBeforePhase("survey")

idx := &recordingIndex{}
opts := codeimpl.Options{Index: idx, ...}
codeimpl.Run(ctx, opts)
assert idx.invalidateCalledAfterRevert()
assert idx.invalidateCalledBeforeGate()

idx := &recordingIndex{}
opts := codeimpl.Options{Index: idx, TaskAttempts: 2, ...}
codeimpl.Run(ctx, opts)
assert idx.invalidateCalledAfterDiscard()

idx := &recordingIndex{}
opts := codeimpl.Options{Index: idx, ...}
codeimpl.Run(ctx, opts)
assert idx.invalidateCalledAfterCommit(task1)
assert idx.invalidateCalledBeforePhase(task2)

idx := &recordingIndex{}
opts := codeimpl.Options{Index: idx, Repair: true, ...}
codeimpl.Run(ctx, opts)
assert idx.invalidateCalledAfterRepairCommit()
assert idx.invalidateCalledBeforeFirstTask()

idx := &recordingIndex{}
opts := codeimpl.Options{Index: idx, Repair: true, ...}
codeimpl.Run(ctx, opts)
assert idx.invalidateCalledAfterRepairAfterTaskCommit()
assert idx.invalidateCalledBeforeTaskCommit()

idxIssue := &recordingIndex{}
idxSpec := &recordingIndex{}
issuetriage.Run(ctx, issuetriage.Options{Index: idxIssue, ...})
specgen.Run(ctx, specgen.Options{Index: idxSpec, ...})
assert idxIssue.invalidateCalls == 0
assert idxSpec.invalidateCalls == 0
